// 本試験対策（学校別）新規校・組A：筑波大学附属高等学校（course: 'koko-tsukuba'、高校受験）向けの自作問題。数学（sansu）・英語（eigo）・国語（kokugo）の各40問（ID _01〜_40）＝120問。
// 実際の過去問ではない自作。動く図解は data/figures-honshiken-school-koko-tsukuba-A.ts に同じIDで置く（数学のみ。数学40問のうち18問に7枚以上のスライド）。理科・社会は組Bが担当。
