//  ・学校：筑波大学附属高等学校。東京都文京区大塚（ja.wikipedia.org「筑波大学附属中学校・高等学校」で確認）。男女共学。高校の1学年は240名（同ページ）。附属中学校から高校へは内部連絡入試（男女それぞれ上位80名が進学。同ページ）があり、この問題集は外部（高校入試）受験生向けの準備として作った。
//  ・高校募集の有無・募集人数：同ページの記述だけでは確認できなかった（未確認）。
//  ・入試の科目・時間・配点・大問の数と並び・出題比率：出典で確認できなかった（未確認）。学校の公式サイトは取得できる許可に入っていない。以下は「難関国立附属の高校入試で一般にいわれる傾向」に沿った方向性であり、事実としては断定しない。
//  ・準拠のしかた（概要）：
//    数学＝思考力を問う小問・関数（放物線と直線・動点）・平面図形（円周角・相似・三平方・折り返し・面積比）・空間図形（切り口・展開図・回転体・最短）・整数と場合の数（約数・余り・規則性・操作）。途中の考え方が問われる難度に合わせ、計算の工夫を求める問題も入れた。
//    英語＝自作の長文3本（約200〜240語。内容把握・指示語・接続・記述）、文法・語法、会話文、整序、和文英訳、書きかえ、誤り指摘、意見の自由英作文。リスニングは出さない。
//    国語＝漢字・語句・文法の知識、古文（『おくのほそ道』冒頭と句）、自作の小説（弓道）・論説文（便利さと手間）・随筆（祖母の畑）・詩（朝の駅）。課題文を複数の設問で使う型（同じ課題文に4〜6問）を含め、記述（字数制限つき）と条件作文を入れた。
//
// ■題材一覧（同じ学校の傾向問題 data/school_koko-tsukuba.ts とは別の担当。題材が重ならないように記録）
//  ・数学：√の計算・和と差の積の工夫（2026²−2024×2028）・式の値・2次方程式の解と係数・食塩水・√の中を平方数に・連続3数の平方和・3けたの3の倍数・さいころと5の倍数・四分位範囲／放物線 y＝(1/2)x² の2点と面積・変化の割合・正三角形OAB・原点を通る面積の二等分・長方形の動点・2直線とx軸の三角形／弧の比と角・台形の対角線と面積比・角の二等分線・折り返し・接線と弦・平行四辺形の中の三角形／立方体の切り口（ひし形）・円錐の展開図・球の切り口・正四角すい・直方体の最短・斜辺を軸にした回転体・立方体の頂点から面への垂線・円錐形の容器／段と並びの規則・碁石・1/m＋1/n＝1/6・約数が15個・余りの条件・硬貨・カードの確率・操作のくり返し／放物線上の動点の面積・弓形。
//  ・英語：関係代名詞（whose）・間接疑問・分詞の後置修飾・群動詞の受け身・the＋比較級・make＋原形・too…to・現在完了（継続）・look forward to・命令文，or／整序3・和文英訳3・会話文3／長文3本（紙と画面の読書・祖父の時計・学校の菜園）各5問／書きかえ2・誤り指摘2・自由英作文2。長文3本はすべて自作。
//  ・国語：漢字・四字熟語・慣用句・敬語・活用形／古文『おくのほそ道』冒頭と句5問／小説「弓道の的」6問／論説文「便利さのゆくえ」6問／随筆「祖母の畑」4問／詩「朝の駅」3問／文学史・助動詞「れる」・故事成語・文の整序・条件作文・要約・書き取り・熟語の構成。課題文・詩はすべて自作。
//
// ■出典で確認できなかった点
//  ・入試の科目・時間・配点・大問構成・高校募集人員（上記のとおり未確認）。
//  ・古文：『おくのほそ道』冒頭と句の字句は ja.wikisource.org「おくのほそ道」（底本は旧字・旧かな）で確認した。本問題集では読みやすいように漢字・かなの表記を改めて載せている（本文中にもその旨を書いた）。
//  ・国語の「取りつく島もない」「臨機応変」などの意味、文学史の組み合わせ、英語の文法事項は、学校教育で一般に扱われる内容による。

