    "explanation": "【何を聞かれているか】3けたの整数のうち、6の倍数の個数を数える。\n【なぜそうなるのか】6の倍数は、2でも3でもわり切れる数。2の倍数は「一の位が偶数」、3の倍数は「各位の数字の和が3の倍数」。さらに、0は百の位に置けない。だから、先に「和が3の倍数になる3枚の組」を決め、そのあとで、組ごとに「一の位が偶数で、百の位が0でない並べ方」を数える。\n【ステップ1】6枚から3枚の組で、和が3の倍数になるものは8組：{0，1，2}、{0，1，5}、{0，2，4}、{0，4，5}、{1，2，3}、{1，3，5}、{2，3，4}、{3，4，5}。\n【ステップ2】一の位が偶数になる並べ方を、組ごとに数える。{0，1，2}は102、120、210の3個。{0，1，5}は150、510の2個。{0，2，4}は204、240、402、420の4個。{0，4，5}は450、504、540の3個。\n【ステップ3】{1，2，3}は132、312の2個。{1，3，5}は偶数がないので0個。{2，3，4}は234、324、342、432の4個。{3，4，5}は354、534の2個。\n【ステップ4】合計は 3＋2＋4＋3＋2＋0＋4＋2＝20個。\n【答え】20個\n【確かめ】書き出した20個を、6でわる。102÷6＝17、120÷6＝20、132÷6＝22、150÷6＝25、…どれも6でわり切れる。\n【よくあるまちがい】3の倍数だけを数えて、一の位が偶数という条件を使い忘れる。0を百の位に置いた「012」のような並びを数える。",
    "pitfall": "3の倍数だけ数えて、偶数の条件を忘れる。",
    "memoryTip": "6の倍数＝2の倍数かつ3の倍数。一の位が偶数で、各位の和が3の倍数。"
