    "explanation": "【何を聞かれているか】直方体の表面を通る最短の糸の長さを求める。\n【なぜそうなるのか】立体の上で2点を結ぶ最短の道は、表面を平らに広げたとき、2点を結ぶ直線になる。AからGへは、3つの辺の長さ（2、4、6）から、どの2面を通るかによって、3通りの広げ方がある。それぞれ、直角三角形の斜辺として三平方の定理で長さが出せる。\n【ステップ1】2、4、6のうち、2つの辺をたした長さと、残る1つの辺で直角三角形をつくる。(2＋4)と6、(2＋6)と4、(4＋6)と2の3通り。\n【ステップ2】(2＋4)²＋6²＝36＋36＝72。\n【ステップ3】(2＋6)²＋4²＝64＋16＝80。\n【ステップ4】(4＋6)²＋2²＝100＋4＝104。\n【ステップ5】最短は72の場合で √72＝6√2cm。（もっとも長い辺6を、たさずに残す形が最短）\n【答え】6√2cm\n【確かめ】√72≒8.5、√80≒8.9、√104≒10.2。3つの中で√72がもっとも小さい。直方体の対角線 √(4＋16＋36)＝√56≒7.5よりは長く、立体の中を通らない分だけ長くなっている。\n【よくあるまちがい】展開の仕方を1通りだけ調べて答えにしてしまう。長い辺をたさずに残す形が最短になることを覚えておくと、確かめるときに便利。また、2＋4＋6 のように3辺を全部たす。または √72 を 6√2 に直さずに答える（どちらでも正解）。",
