    "explanation": "【何を聞かれているか】直角三角形を斜辺のまわりに回転させた立体の体積を求める。\n【なぜそうなるのか】Cから斜辺ABにおろした垂線の足をHとすると、回転すると△ACHと△BCHは、それぞれ円錐になる。2つの円錐は、底面（半径CH）を共有しているので、底面積×(高さの合計)÷3で、まとめて体積が出る。高さの合計はAH＋HB＝ABの5cm。\n【ステップ1】△ABCの面積を2通りで表す。(1/2)×AC×BC＝(1/2)×AB×CH より 4×3＝5×CH、CH＝12/5cm。\n【ステップ2】2つの円錐の底面の半径は CH＝12/5cm。底面積＝π×(12/5)²＝144π/25。\n【ステップ3】2つの円錐の高さの合計は AH＋HB＝AB＝5cm。\n【ステップ4】体積＝(144π/25)×5÷3＝48π/5。\n【答え】48π/5 cm³\n【確かめ】AH＝AC²÷AB＝16/5、HB＝BC²÷AB＝9/5（相似な三角形から）。1つ目の円錐は (144π/25)×(16/5)÷3＝768π/125、2つ目は (144π/25)×(9/5)÷3＝432π/125。合計 1200π/125＝48π/5で一致する。\n【よくあるまちがい】斜辺ABを軸にしたのに、ACやBCを軸にした円錐（半径3や4）だと考えてしまう。斜辺を軸にするときは、半径がCHになることに気づく。",
