    "explanation": "【何を聞かれているか】2枚の積が偶数になる確率を求める。\n【なぜそうなるのか】2つの数の積は、少なくとも一方が偶数なら偶数、両方が奇数のときだけ奇数になる。「偶数」の場合は種類が多いが、「奇数」の場合は1通りの条件だけなので、数えやすい。全体の確率1から、積が奇数になる確率をひく。\n【ステップ1】2枚のひき方は全部で 9×8÷2＝36通り。\n【ステップ2】積が奇数になるのは、2枚とも奇数のとき。奇数は1、3、5、7、9の5枚。5枚から2枚えらぶ方法は 5×4÷2＝10通り。\n【ステップ3】積が奇数になる確率＝10/36＝5/18。\n【ステップ4】積が偶数になる確率＝1−5/18＝13/18。\n【答え】13/18\n【確かめ】積が偶数の場合の数を直接数える。偶数カードが2枚入る場合は 4×3÷2＝6通り、偶数1枚と奇数1枚の場合は 4×5＝20通り。合わせて26通りで、26/36＝13/18と一致する。\n【よくあるまちがい】同時にひくのに、順番をつけて 9×8＝72通りで全体を数え、奇数のほうを 5×4÷2＝10通りで数える。分母と分子で、順番の考え方をそろえる。",
