    "explanation": "【何を聞かれているか】関係代名詞の使い分け。\n【なぜそうなるのか】関係代名詞は、あとに続く語の役割で決まる。(　)のすぐあとに名詞（father）が来て、「その友だちの父親」という持ち主の関係を表すときは、who や which ではなく whose を使う。who は主語の役割（あとに動詞が来る）、which は物に使う。\n【ステップ1】文の意味は「私には、（その）父親が有名なピアニストである友だちがいる」。\n【ステップ2】a friend と father は「友だちの父親」という持ち主の関係。\n【ステップ3】持ち主を表す関係代名詞は whose。whose＋名詞＋動詞、の形になる。\n【答え】whose\n【確かめ】He is a friend. His father is a famous pianist. の2文を1つにしたと考えると、His が whose に変わっている。選択肢のうち、who はあとに動詞が来る形（a friend who plays the piano）、which は物、where は場所なので合わない。\n【よくあるまちがい】who を選んで I have a friend who father… と書いてしまう。who のあとには動詞が来る。名詞が来るなら whose。",
