    "explanation": "【何を聞かれているか】現在完了形の疑問文の語順を組み立てる。\n【なぜそうなるのか】「どのくらい長く〜していますか」は How long have you ...? で、継続の現在完了形を使う。「飼う（持つ）」は have で、現在完了形では have＋had（過去分詞）となる。疑問詞 How long のあとは、疑問文の語順（have you）になる。\n【ステップ1】疑問詞は How long。文の最初に置く。\n【ステップ2】現在完了形の疑問文は、have＋主語＋過去分詞。have you had。\n【ステップ3】目的語は the dog。つなぐと How long have you had the dog?\n【答え】How long have you had the dog?\n【確かめ】7語すべて使っている。have が2回出てくる（have と had）が、前が助動詞、後ろが過去分詞で、役割がちがう。\n【よくあるまちがい】How long you have had the dog? と、疑問文の語順にしない。have が主語の前に出る。",
