    "explanation": "【何を聞かれているか】下線部の指す内容を、前の文からさがす。\n【なぜそうなるのか】the same experience（同じ経験）は、直前に書かれた筆者の経験を指している。その直前の文は、When I read a long story on the tablet, I often forgot what I had read on the previous page.（長い話をタブレットで読むと、前のページで読んだことをよく忘れた）。この経験を、Yui もした、ということ。\n【ステップ1】下線部の直前の文を読む。\n【ステップ2】直前の文：When I read a long story on the tablet, I often forgot what I had read on the previous page.\n【ステップ3】つまり「長い物語をタブレットで読むと、前のページの内容を忘れる」経験。\n【答え】長い物語をタブレットで読むと、前のページで読んだことをよく忘れてしまったこと。\n【確かめ】「かばんが軽くなってうれしかった」は同じ段落の前の経験だが、問題（problem）とは別の内容。「教科書の規則が変わったこと」は学校の出来事で、経験とは言えない。\n【よくあるまちがい】「かばんが軽くなった」を選ぶ。下線部の直前の文を確かめず、前のほうの内容に飛びつく。",
