    "question": "本文によると、紙で読むと、画面で読むよりも長い文章を覚えやすいと言われるのはなぜですか。日本語で、50字以内で説明しなさい。",
    "answer": "ページの厚みで、どこまで読んだかを手の感覚でつかめるので、物語の全体像を頭の中に作りやすいから。",
    "hint": "第2段落で、紙のときと画面のときの「どこまで読んだか」の感じ方のちがいが説明されている。",
    "explanation": "【何を聞かれているか】理由を、本文から探して日本語でまとめる。\n【なぜそうなるのか】理由を問う問題は、本文で理由を説明している文を探す。第2段落に、on paper, we can feel how far we have read by the thickness of the pages in our hands.（紙では、手の中のページの厚みで、どこまで読んだかを感じられる）と、On a screen, the words just move up and down, so it is harder to make a map of the story in our head.（画面では文字が上下に動くだけなので、物語の地図を頭の中に作りにくい）とある。この2文の「紙のよさ」の部分をまとめる。\n【ステップ1】本文の理由の文：we can feel how far we have read by the thickness of the pages。\n【ステップ2】もう一つ：it is harder to make a map of the story in our head（画面では地図を作りにくい）。\n【ステップ3】これらを、「紙では〜できるから」の形でまとめる。\n【答え】ページの厚みで、どこまで読んだかを手の感覚でつかめるので、物語の全体像を頭の中に作りやすいから。\n【確かめ】字数を数える。「ページの厚みで、どこまで読んだかを手の感覚でつかめるので、物語の全体像を頭の中に作りやすいから。」は48字で、50字以内に収まっている。\n【よくあるまちがい】画面のわるいところ（文字が動くだけ）だけを書いて、紙のよいところ（厚みでわかる）を書かない。また、「〜から」で終えず、理由の文になっていない。",
    "pitfall": "紙のよさでなく、画面のわるさだけを書く。",
    "memoryTip": "理由は、「〜から」で終える。本文の該当部分を探す。",
    "passage": "Last year, our school changed its rule about textbooks. Until then, we carried heavy paper books every day. Now each student has a tablet, and most of the books are on it. At first, I was very happy because my bag became much lighter. However, after a few weeks, I noticed a problem. When I read a long story on the tablet, I often forgot what I had read on the previous page. My classmate Yui had the same experience.\n\nOur teacher, Ms. Kato, said that many researchers have studied this topic. According to her, some studies show that people remember long texts better when they read them on paper. She explained that on paper, we can feel how far we have read by the thickness of the pages in our hands. On a screen, the words just move up and down, so it is harder to make a map of the story in our head. But she also told us that screens have good points. For example, we can search for a word in a second and make the letters bigger when they are hard to see.\n\nAfter the class, Yui and I decided to try a new way. We use the tablet for homework and dictionaries, but we read long stories on paper from the library. I think the best way is not to choose one over the other, but to use each of them in the right place.",
