    "explanation": "【何を聞かれているか】下線部の内容を、直後の文から説明する。\n【なぜそうなるのか】something more important than watches（時計よりも大切なもの）は、その直後の文で言いかえられている。You know how to wait, and how to think when you don't understand.（あなたは、待つ方法と、わからないときに考える方法を知っている）。この2つを、日本語でまとめる。\n【ステップ1】下線部のあとを読む：You know how to wait, and how to think when you don't understand.\n【ステップ2】前半：how to wait＝待つ方法。\n【ステップ3】後半：how to think when you don't understand＝わからないときに考える方法。\n【答え】待つことと、わからないときに自分で考える方法を身につけたこと。\n【確かめ】字数を数える。「待つことと、わからないときに自分で考える方法を身につけたこと。」は31字で、40字以内。待つことと考えることの2つが入っている。\n【よくあるまちがい】「時計を直す方法」と書く。それは時計についての知識で、「時計よりも大切なもの」にならない。また、待つことか考えることの片方だけを書く。",
    "pitfall": "時計の直し方と書く。2つのうち1つだけ書く。",
