    "passage": "When I was twelve, my grandfather gave me an old watch. It was not beautiful. The glass had a small crack, and the leather band was almost broken. \"It stopped working many years ago,\" he said. \"But I think you can fix it.\" I was surprised because I knew nothing about watches.\n\nThat night, I opened the back of the watch with a small screwdriver. Inside were hundreds of tiny parts. I felt excited and a little afraid. Every weekend after that, I visited my grandfather's workshop. He did not tell me how to fix it. Instead, he asked questions. \"What do you think this part does?\" or \"Why is this one moving, but that one isn't?\" At first, his questions made me angry. I wanted a quick answer. But slowly, I began to enjoy thinking by myself.\n\nAfter three months, the watch started to move. The second hand shook, and then it moved smoothly around the face. I ran to show my grandfather. He smiled and said, \"Now you know something more important than watches. You know how to wait, and how to think when you don't understand.\" Today, he is no longer with us, but I wear that watch every day. When I have a hard problem, I look at it and remember his voice.",
