    "explanation": "【何を聞かれているか】本文の内容に合う選択肢を、1つずつ確かめて選ぶ。\n【なぜそうなるのか】選択肢を1つずつ本文と照らす。第3段落の冒頭に After three months, the watch started to move. とあり、筆者が約3か月後に時計を動かしたことがわかる。ほかの選択肢は、本文の内容と食いちがっている。\n【ステップ1】「祖父が直し方を順に教えた」→ He did not tell me how to fix it. と合わない。\n【ステップ2】「時計を直したのは約3か月後」→ After three months, the watch started to move. と合う。\n【ステップ3】「時計は美しかった」→ It was not beautiful. と合わない。「祖父はいまも同居している」→ he is no longer with us と合わない。\n【答え】The writer fixed the watch after about three months.\n【確かめ】正しい選択肢は、本文の After three months（3か月後）と同じ内容。ほかの3つは、それぞれ本文の反対の内容。\n【よくあるまちがい】「祖父がステップごとに教えた」を選ぶ。本文では、祖父は質問をするだけで、直し方は教えなかった。",
