    "explanation": "【何を聞かれているか】意見と理由を、英語で組み立てる。\n【なぜそうなるのか】自由英作文は、①自分の意見（賛成か反対か）、②理由（具体的に2つ）、③まとめ、の順に書くと、読む人に伝わりやすい。1文を短くして、文法の誤りを避けることも大切。正解は1つではないので、型を守って書けているかが評価のポイント。\n【ステップ1】意見を書く：I think students should be allowed to use smartphones in class.\n【ステップ2】理由を2つ書く：First, …. Second, ….\n【ステップ3】条件やまとめを1文加える：Of course, we need clear rules, so ….\n【ステップ4】全体の語数が約40語（35〜50語）になっているか数える。\n【答え】意見（賛成）と、理由2つ、まとめの条件を書いた英文。（模範解答の例）\n【確かめ】模範解答は約49語。意見、理由2つ（辞書・黒板の撮影）、ルールの必要性、の3つの要素が入っている。\n【よくあるまちがい】理由を書かずに、意見だけを繰り返す。または、日本語をそのまま英語にして、文が長くなり、文法の誤りが増える。",
