    "explanation": "【何を聞かれているか】古文の語の意味を、前後の文から考える。\n【なぜそうなるのか】「過客」は、通り過ぎていく旅人。この文は「月日は永遠の旅人である」と述べ、その次の「行きかふ年もまた旅人なり」で、同じ内容をくり返している（対句に近い表現）。だから「過客」は、「旅人」とほぼ同じ意味で使われている。「過」は通り過ぎる、「客」は旅人（よその人）。\n【ステップ1】「月日は百代の過客」と「行きかふ年もまた旅人」は、同じ内容を言いかえている。\n【ステップ2】「また」は「〜もまた〜」で、同じものを重ねる語。\n【ステップ3】「過客」＝「旅人（通り過ぎていく人）」。\n【答え】通り過ぎていく旅人\n【確かめ】「百代」は「永遠」、つまり月日は、永遠に旅を続けていく旅人だということ。時間の流れを、旅人にたとえた表現（隠喩）。\n【よくあるまちがい】「過客」を、「過去の客」や「お客さん」と取りちがえる。「客」には「旅人」の意味もある。",
