    "explanation": "【何を聞かれているか】理由を、傍線部の直後の文から読み取る。\n【なぜそうなるのか】傍線部のすぐあとに「当てようとしなければ、当たるはずがない」とある。透は、弓は当てようとしなければ当たらないものだと考えていた。だから、先生の「当てようと思って当たったことはほとんどない」という言葉が、理解できなかった。\n【ステップ1】傍線部の直後の文を読む。\n【ステップ2】「当てようとしなければ、当たるはずがない」。\n【ステップ3】透の考えと、先生の言葉が反対なので、意味がわからなかった。\n【答え】当てようとしなければ、当たるはずがないと考えていたから。\n【確かめ】先生の言葉と透の考えが、まったく逆になっている。のちに透が、当てようとしないで当てることができた場面で、考えが変わることがわかる。\n【よくあるまちがい】「先生の言葉が小さかったから」を選ぶ。理由は透の考えにある。",
    "pitfall": "直後の文を読まずに選ぶ。",
    "memoryTip": "理由は傍線部の直後にある。",
    "passage": "　放課後の弓道場には、秋の光が斜めに差しこんでいた。\n　透は、最後の大会を三日後に控えて、一人で射場に立っていた。さきほどから、矢は五本続けて的を外れている。弦を引く左腕が、わずかに震えているのが自分でもわかった。\n「力が入りすぎだ。」\n　背後から声がして、振り返ると顧問の小野先生が立っていた。先生は何も言わず、透のとなりに並んで弓を構えた。放たれた矢は、静かな音を立てて的の中心に吸いこまれた。\n「うまいですね。」透は、思わず皮肉のような口調で言ってしまった。すぐにしまったと思ったが、先生は少し笑っただけだった。\n「うまい、か。私はな、三十年やっていて、的に当てようと思って当たったことは、ほとんどないんだ。」\n　透には、その意味がわからなかった。当てようとしなければ、当たるはずがない。\n「当てようとするほど、体は固くなる。体が固くなれば、矢は思いとは別の方向に飛んでいく。だから、的のことは忘れて、自分の呼吸だけを見る。そうすると、いつのまにか矢は、的に向かっているものだ。」\n　先生が去ったあと、透はもう一度弓を構えた。的を見ずに、息を吸い、吐く。左腕の震えは、いつのまにか消えていた。放たれた矢は、乾いた音とともに、的のまん中より少し左に刺さった。\n　透は、しばらく動けなかった。初めて、当てようとしないで当てたのだ。うれしさよりも先に、これまで自分が見ていたのは的ではなく「失敗する自分」だったのかもしれない、という思いが胸に広がった。\n　夕日が、的の白い面を赤く染めていた。",
