    "explanation": "【何を聞かれているか】前後の段落の関係から、接続語を選ぶ。\n【なぜそうなるのか】第①段落は、便利になって自由な時間が生まれた、というよい面を述べている。第②段落は、「何かを失ったのではないか」と、反対の見方を出している。前の内容と反対の内容を述べるときに使う接続語は「しかし」。\n【ステップ1】第①段落：便利になったよい面。\n【ステップ2】第②段落：失ったものがあるのではないか（反対の見方）。\n【ステップ3】反対の内容をつなぐ接続語は「しかし」。\n【答え】しかし\n【確かめ】「だから」は原因と結果、「つまり」は言いかえ、「たとえば」は例を出すときに使う。ここでは、いずれも合わない。\n【よくあるまちがい】「だから」を選ぶ。「便利になった。だから失ったものがある」では、意味が通らない。",
