    "passage": "【便利さのゆくえ】\n①　私たちの生活は、この百年で驚くほど便利になった。洗濯機は洗う手間を、冷蔵庫は買い物の回数を、スマートフォンは調べものの時間を、それぞれ減らしてくれた。手間が減れば、その分だけ自由な時間が生まれる。便利さが人を幸せにすると考えられてきたのは、そのためである。\n②　しかし、手間が減ったことは、同時に何かを失ったことでもあるのではないか。たとえば手紙である。手紙は、書いてから相手に届くまで数日かかり、返事が来るまでにはさらに時間がかかる。その間、人は相手の様子を思い浮かべ、何と書いてくるだろうかと待つ。この「待つ時間」が、相手を想う気持ちを育ててきたのだと思う。\n③　即座にメッセージが届く現代では、この待つ時間はほとんどなくなった。返事が数分来ないだけで、人は不安になる。待つ力が弱くなったのである。便利になったことで、手間が省かれただけでなく、手間のなかにあった大切な時間までもが、一緒に省かれてしまったのだ。\n④　もちろん、昔に戻るべきだと言いたいのではない。便利さは、本来、人が大切なことに時間を使うための手段にすぎない。問題は、便利さを手に入れること自体が目的になり、何のために時間を生み出したのかを忘れてしまうことである。\n⑤　手間を省くときには、その手間が自分にとって何を育てていたのかを、一度立ち止まって考えてみたい。残すべき手間と、手放してよい手間を見分けること。それが、便利な時代を賢く生きるための、私たちの課題である。",
